// Local entry-flow preview; this screen is not an authentication/security boundary.
let previewSession=null,entryTab='register',entryEmail='',entryMessage='';const workspaceRender=render;
const entryRoot=document.createElement('section');entryRoot.id='entryRoot';document.body.prepend(entryRoot);
function registrationFields(){return `<form id="entryRegister" class="entry-form"><label>الاسم بالكامل<input name="name" required maxlength="120" autocomplete="name" placeholder="اسمك زي ما تحب يظهر للفريق"></label><div class="entry-field-row"><label>البريد الإلكتروني<input name="email" type="email" required autocomplete="email" dir="ltr" placeholder="name@example.com"></label><label>رقم الموبايل<input name="phone" type="tel" required autocomplete="tel" dir="ltr" placeholder="01xxxxxxxxx"></label></div><div class="entry-field-row"><label>الوظيفة<select name="position" required>${Object.keys(positions).map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>الفرع<select name="branch" required>${db.branches.map(b=>`<option>${esc(b.name)}</option>`).join('')}</select></label></div><div class="entry-flow-hint"><span>١. تسجّل بياناتك</span><span>٢. الإدارة توافق</span><span>٣. تبدأ يومك</span></div><button class="primary entry-submit">إرسال طلب تسجيل موظف ←</button><p class="entry-footnote">طلبك بيتراجع مرة واحدة. الوظيفة والأكسس النهائيين تحددهم الإدارة بعد الموافقة.</p></form>`}
function loginFields(){return `<form id="entryLogin" class="entry-form"><label>البريد الإلكتروني المسجل<input name="email" type="email" required autocomplete="email" dir="ltr" placeholder="name@example.com" value="${esc(entryEmail)}"></label><button class="primary entry-submit">متابعة إلى حساب الموظف ←</button><div class="entry-preview-notice">الدخول هنا تجربة على نفس المتصفح، بدون كلمة مرور. حسابات الدخول الآمنة ومزامنة الأجهزة لم يتم ربطها بعد.</div><button type="button" class="entry-text-button" id="backRegister">لسه معندكش حساب؟ سجّل كموظف جديد</button></form>`}
function entryView(){document.body.classList.add('entry-mode');entryRoot.hidden=false;entryRoot.innerHTML=`<div class="entry-shell"><div class="entry-brand-mobile">ϟ ENERGY <span>STAFF</span></div><article class="entry-story"><a class="entry-logo" href="#">ϟ <b>ENERGY<small>STAFF MANAGEMENT</small></b></a><span class="entry-eyebrow">ONE TEAM. ONE ENERGY.</span><h1>كل يوم جديد.<br>طاقة أقوى.<br><em>فريق واحد.</em></h1><p>مساحتك لتنظيم يومك في الجيم.<br>من أول حضورك لآخر مهمة تنجزها.</p><div class="entry-story-features"><div><b>⌖</b><span>حضور من الفرع<small>حضور وانصراف داخل نطاق ٨٠ متر</small></span></div><div><b>☑</b><span>يومك واضح<small>مهامك، متابعاتك، وكل تفاصيل شغلك</small></span></div><div><b>↗</b><span>التزامك ظاهر<small>سجل الأداء وساعات الحضور</small></span></div></div><small class="entry-copyright">ENERGY CLUB • BUILT FOR OUR PEOPLE</small></article><article class="entry-panel"><div class="entry-panel-top"><span class="entry-preview-badge">نسخة معاينة</span><button id="entryAdmin" class="entry-admin">معاينة الإدارة ↗</button></div><div class="entry-panel-main"><div class="entry-eyebrow">WELCOME TO THE TEAM</div><h2>${entryTab==='register'?'ابدأ حكايتك مع الفريق.':'أهلًا بيك من جديد.'}</h2><p>${entryTab==='register'?'سجّل كموظف جديد، وخلي خطوتك الأولى بسيطة.':'ادخل بالبريد اللي سجلت بيه بعد موافقة الإدارة.'}</p><div class="entry-tabs" role="tablist" aria-label="طريقة الدخول"><button id="registerTab" role="tab" aria-selected="${entryTab==='register'}" class="${entryTab==='register'?'selected':''}">تسجيل موظف جديد</button><button id="loginTab" role="tab" aria-selected="${entryTab==='login'}" class="${entryTab==='login'?'selected':''}">دخول موظف</button></div>${entryMessage?`<div class="entry-status" role="status">${esc(entryMessage)}</div>`:''}${entryTab==='register'?registrationFields():loginFields()}<div class="entry-local-note">المعاينة تحفظ البيانات على هذا المتصفح فقط. لا تدخل كلمات مرور أو بيانات عملاء حقيقية هنا.</div></div><footer>ENERGY STAFF © 2026 <span>إدارة أذكى. فريق أقوى.</span></footer></article></div>`;$('#registerTab').onclick=()=>{entryTab='register';entryMessage='';entryView()};$('#loginTab').onclick=()=>{entryTab='login';entryMessage='';entryView()};$('#backRegister')?.addEventListener('click',()=>{entryTab='register';entryMessage='';entryView()});$('#entryAdmin').onclick=()=>enterWorkspace({kind:'admin'});$('#entryRegister')?.addEventListener('submit',e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));newJoin(data);entryEmail=data.email.trim().toLowerCase();entryTab='login';entryMessage='تم تسجيل طلبك. طلبك دلوقتي بانتظار موافقة الإدارة الأولى؛ هتقدر تدخل مساحة الموظف بعد القبول على هذا المتصفح.';save();entryView()}catch(err){entryMessage=err.message;entryView()}});$('#entryLogin')?.addEventListener('submit',e=>{e.preventDefault();const email=String(new FormData(e.target).get('email')).trim().toLowerCase();entryEmail=email;const result=resolvePreviewLogin(email);if(result.ok)enterWorkspace({kind:'employee',employeeId:result.employee.id});else{entryMessage=result.message;entryView()}})}
function resolvePreviewLogin(email){const request=db.joinRequests.find(r=>r.email===email&&r.status!=='rejected')||db.joinRequests.filter(r=>r.email===email).at(-1);if(!request)return {ok:false,message:'مفيش طلب تسجيل بهذا البريد على المتصفح ده. سجّل موظف جديد الأول.'};if(request.status==='pending')return {ok:false,message:'طلبك بانتظار موافقة الإدارة. حساب الموظف غير متاح قبل الموافقة.'};if(request.status==='rejected')return {ok:false,message:'طلب التسجيل لم يُقبل. تواصل مع الإدارة لمراجعة الطلب.'};const employee=db.staff.find(s=>s.id===request.employeeId),account=db.accounts.find(a=>a.employeeId===request.employeeId);if(!employee||account?.disabled)return {ok:false,message:'مساحة الموظف غير متاحة حاليًا؛ راجع الإدارة.'};return {ok:true,employee}}
function enterWorkspace(session){previewSession=session;document.body.classList.remove('entry-mode');entryRoot.hidden=true;role=session.kind==='employee'?'الموظف':'الإدارة';$('#role').value=role;if(session.kind==='employee')selectedEmployee=session.employeeId;page=session.kind==='employee'?'overview':'join-approvals';render()}
function leaveWorkspace(){previewSession=null;role='الإدارة';page='overview';entryTab='login';entryMessage='';$('#modal').close();entryView()}
function organizeWorkspaceNav(){if(role!=='الإدارة')return;const groups=[['الفريق والحسابات',['overview','join-approvals','accounts','staff','archive','permissions','locations']],['التشغيل اليومي',['attendance','records','manual','breaks','daily-team','tasks','coach-log','sales-work','requests','shifts']],['الإدارة والتقارير',['score','rules','reports','payroll']]];const buttons=[...document.querySelectorAll('#nav [data-page]')];const nav=$('#nav');nav.innerHTML='';for(const [label,ids]of groups){const heading=document.createElement('p');heading.className='nav-group-label';heading.textContent=label;nav.append(heading);for(const id of ids){const b=buttons.find(b=>b.dataset.page===id);if(b)nav.append(b)}}}
render=function(){if(!previewSession){entryView();return}if(previewSession.kind==='employee'){const s=db.staff.find(s=>s.id===previewSession.employeeId),account=db.accounts.find(a=>a.employeeId===previewSession.employeeId);if(!s||account?.disabled){previewSession=null;entryMessage='مساحة الموظف موقوفة أو مؤرشفة؛ راجع الإدارة.';entryView();return}role='الموظف';selectedEmployee=s.id}workspaceRender();entryRoot.hidden=true;document.body.classList.remove('entry-mode');$('#role').hidden=previewSession.kind==='employee';if(previewSession.kind==='employee'){$('#employeeSelect')?.setAttribute('hidden','');$('#teamPreviewEmployee')?.setAttribute('hidden','');document.querySelectorAll('#nav [data-page="join"]').forEach(b=>b.hidden=true)}organizeWorkspaceNav();if(!$('#workspaceExit')){const b=document.createElement('button');b.id='workspaceExit';b.className='workspace-exit';b.textContent='الخروج إلى واجهة الدخول';b.onclick=leaveWorkspace;$('.header-actions').append(b)}};
render();
